import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/pages/Home/Home'
import Details from '@/pages/Details/Details'
import Submit from '@/pages/Submit/Submit'

Vue.use(Router)

export default new Router({
	routes: [{
			path: '/menu',
			name: 'Home',
			component: Home,
			meta: {
				keepAlive: true
			}
		},
		{
			path: '/details',
			name: 'Details',
			component: Details,
			meta: {
				keepAlive: false
			}
		},
		{
			path: '/submit',
			name: 'Submit',
			component: Submit,
			meta: {
				keepAlive: false
			}
		}
	],
})


