<template>
	<div class="container">
		<div class="showOff_container" v-if="ad_flag&&(result.video_url||result.pic_arr)">
			<video id="myVideo" class="video-js" v-if="result.video_url">
				<source :src="result.video_url" type="video/mp4">
			</video>
			<swiper :options="swiperOption" v-if="result.pic_arr" id="swiper">
				<swiper-slide v-for="(item,index) in result.pic_arr" :key="index">
					<img :src="item.url" alt="" class="" />
				</swiper-slide>
				<div class="swiper-pagination" slot="pagination"></div>
			</swiper>
			<div class="close" @click="closeAd"></div>
		</div>
		<div class="drawer">
			<div class="middle_container">
				<span class="food_title bold">{{result.name}}</span>
				<div class="price_group">
					<span class="food_now_price HelveticaNeue">${{numberFixed(Number(total_price))}}</span>
					<span class="food_past_price HelveticaNeue" v-if="result.price!=result.o_price">${{numberFixed(Number(o_price))}}</span>
				</div>
				<span :class="[{'less':less_more_toggle_flag},'food_introduction HelveticaNeue']">{{result.describe}}</span>
			</div>
			<div :class="[{'less':less_more_toggle_flag},'bottom_container HelveticaNeue']">
				<div class="special_food_container" v-if="special_food_materials.length!=0">
					<span>{{switchL("特殊食材")}}：</span>
					<div class="showOff_tags orange" v-for="(item,index) in result.special_food_materials" :key="index"><img src="./img/orange_tags.png" alt="" class="orangeIcon" />{{item}}</div>
				</div>
				<div class="food_taste_container" v-if="flavor.length!=0">
					<span>{{switchL('菜品口味')}}：</span>
					<div class="showOff_tags" v-for="(item,index) in result.flavor" :key="index">{{item}}</div>
				</div>
				<div class="text_area" v-if="cook">{{switchL('菜品做法')}}：<span>{{cook}}</span></div>
				<div class="text_area" v-if="material">{{switchL('菜品配料')}}：<span>{{material}}</span></div>
			</div>
			<span class="more_less_toggle HelveticaNeue" v-if="!less_more_toggle_flag&&special_food_materials&&flavor&&cook&&material" @click="change_less_more_toggle"><img src="./img/up_arrow.png" alt="" />{{switchL('展示更少')}}</span>
			<span class="more_less_toggle HelveticaNeue" v-if="less_more_toggle_flag&&special_food_materials&&flavor&&cook&&material" @click="change_less_more_toggle"><img src="./img/noun_down_1247052.png" alt="" />{{switchL('展示更多')}}</span>
		</div>
		<div class="select_section" v-for="(item,indexA) in result.spec_list" :key="'spec_list'+indexA">
			<div class="select_bar HelveticaNeue" @click="toggle_select_area_show(indexA,'spec_list')">
				<span class="select_name">{{item.name}}</span>
				<span class="select_comment" v-if="item.comment">{{item.comment}}</span>
				<img src="./img/noun_down_1247052.png" alt="" v-if="!item.select_area_show" />
				<img src="./img/up_arrow.png" alt="" v-if="item.select_area_show" />
				<!--<span class="select_order_number" v-if="item.variety">已选{{item.order_number}}份</span>-->
			</div>
			<div class="select_area" v-if="item.select_area_show">
				<span v-for="(items,index) in item.list" :key="'spec_list_select'+index" :class="[{'select_tags_active':items.order_number==1},'select_tags']" @click="select_tag(indexA,index)">
					{{items.name}}
				</span>
			</div>
		</div>
		<div class="select_section" v-for="(item,indexA) in result.properties_list" :key="'properties'+indexA">
			<div class="select_bar HelveticaNeue" @click="toggle_select_area_show(indexA,'properties_list')">
				<span class="select_name">{{item.name}}</span>
				<span class="select_comment" v-if="item.comment">{{item.comment}}</span>
				<img src="./img/noun_down_1247052.png" alt="" v-if="!item.select_area_show" />
				<img src="./img/up_arrow.png" alt="" v-if="item.select_area_show" />
				<span class="select_order_number">{{switchL('已选')}}{{item.order_number}}{{switchL('份')}}</span>
			</div>
			<div class="select_area" v-if="item.select_area_show">
				<span v-for="(items,index) in item.val_obj" :key="'properties_select'+index" :class="[{'select_tags_active':items.order_number==1},'select_tags']" @click="select_val(indexA,index)" v-if="items.is_show==1">
					{{items.name}}
				</span>
			</div>
		</div>
		<div class="select_section" v-for="(item,indexA) in result.subsidiary_piece" :key="'subsidiary'+indexA">
			<div class="select_bar HelveticaNeue" @click="toggle_select_area_show(indexA,'subsidiary_piece')">
				<span class="select_name">{{item.name}}</span>
				<span class="select_comment" v-if="item.maxnum!=item.mininum">(<span v-if="item.maxnum!=0">{{switchL('最多选')}}{{item.maxnum}}{{switchL('份')}}</span><span v-if="item.mininum!=0">,{{switchL('最少选')}}{{item.mininum}}{{switchL('份')}}</span>)</span>
				<img src="./img/noun_down_1247052.png" alt="" v-if="!item.select_area_show" />
				<img src="./img/up_arrow.png" alt="" v-if="item.select_area_show" />
				<span class="select_order_number">{{switchL('已选')}}{{item.order_number}}{{switchL('份')}}</span>
			</div>
			<div class="select_area fix" v-if="item.select_area_show">
				<div v-for="(items,indexB) in item.goods" :key="'subsidiary_select'+indexB" :class="[{'fix_src':items.image},'select_food HelveticaNeue',{'fix_more':items.has_spec||items.has_format},{'fix_order':items.order_name.length!=0}]">
					<div v-if="!items.has_spec&&!items.has_format">
						<img :src="items.image" alt="" class="select_food_src" v-if="items.image" />
						<span class="select_food_name">{{items.name}}</span>
						<span class="select_food_comment" v-if="items.price&&items.unit">(+${{items.price}}/{{items.unit}})</span>
						<img src="./img/menu_add.png" alt="" class="select_food_add" @click="add_order_number(indexA,indexB)" />
						<span class="select_food_num" v-if="items.order_number>0">{{items.order_number}}</span>
						<img src="./img/menu_minus.png" alt="" class="select_food_minus" v-if="items.order_number>0" @click="minus_order_number(indexA,indexB)" />
					</div>
					<div v-if="items.has_spec||items.has_format">
						<img :src="items.image" alt="" class="select_food_src" v-if="items.image" />
						<span class="select_food_name">{{items.name}}</span>
						<span class="select_food_comment">({{switchL('多规格')}})</span>
						<span class="select_food_type">{{sort_arr(items.order_name)}}</span>
						<div class="select_more" v-if="!items.selected_more" @click="add_selected_more(indexA,indexB)">{{switchL('选规格')}}</div>
						<div class="select_more" v-if="items.selected_more==1" @click="add_selected_more(indexA,indexB)">{{switchL('加入购物车')}}</div>
						<div v-if="items.selected_more==1">
							<div v-for="(item_three,indexC) in items.spec_list" :key="indexC" class="select_more_area">
								<span>{{item_three.name}}:</span>
								<div v-for="(item_four,indexD) in item_three.list" :key="indexD" @click="changeSubVal(indexA,indexB,indexC,indexD)" :class="[{'select_more_tags_active':item_four.order_number==1},'select_more_tags']">{{item_four.name}}<span v-if="item_four.price">(+${{numberFixed(Number(item_four.price))}})</span></div>
							</div>
							<div v-for="(item_three,indexC) in items.properties_list" :key="indexC" class="select_more_area">
								<span>{{item_three.name}}:</span>
								<div v-for="(item_four,indexD) in item_three.val_obj" :key="indexD" @click="changeSubTag(indexA,indexB,indexC,indexD)" :class="[{'select_more_tags_active':item_four.order_number==1},'select_more_tags']" v-if="item_four.is_show==1">{{item_four.name}}</div>
							</div>
						</div>
						<div v-if="items.selected_more==2">
							<img src="./img/menu_add.png" alt="" class="select_food_add" @click="add_selected_more(indexA,indexB)" />
							<span class="select_food_num" v-if="items.order_number>0">{{items.order_number}}</span>
							<img src="./img/menu_minus.png" alt="" class="select_food_minus" v-if="items.order_number>0" @click="minus_selected_more(indexA,indexB)" />
						</div>
					</div>
				</div>
			</div>
		</div>
		<span class="limit_sign" v-if="order_number>=result.stock&&result.stock!=-1">{{switchL('已达上限')}}</span>
		<div class="button_group">
			<div class="add_button" @click="add_total_order_number"></div>
			<span>{{order_number}}</span>
			<div class="minus_button" @click="minus_total_order_number"></div>
		</div>
		<div class="submit_button" @click="back_to_menu()">
			<span class="add_to_cart">{{switchL('添加到购物车')}}</span>
			<span class="total">${{numberFixed(Number(total_price)*order_number)}}</span>
		</div>
	</div>
</template>

<script>
	import { mapState, mapActions, mapGetters, mapMutations } from 'vuex';
	export default {
		name: "Details",
		data() {
			return {
				id: '',
				result: {},
				index: 0,
				subIndex: 0,
				currentFood: {},
				total_price: 0,
				order_number: 1,
				productParams: [],
				submit_obj: {},
				ad_flag: true,
				uniqueness_number: [],
				uniqueness_mumber: [],
				swiperOption: {
					autoplay: true,
					slidesPerView: 'auto',
					pagination: {
						el: '.swiper-pagination',
						clickable: true
					}
				},
				cook: "",
				material: '',
				less_more_toggle_flag: false,
				scrollTop: 0,
				special_food_materials: [],
				flavor: [],
				o_price:0
			};
		},
		computed: {
			...mapState(["count", "totalPrice", "cart","foodList","submit_menu"]),
			numberFixed() {
				return function(num) {
					return Number(num).toFixed(2);
				}
			},
			sort_arr(){
				return function(arr){
					var new_arr = [];
					for(var i = 0;i<arr.length;i++){
						var index_el = arr[i];
						var num = 0;
						for(var j = i;j<arr.length;j++){
							if(arr[i] == arr[j]){
								num++;
//								if(i!=j){
//									arr[j] = ""
//								}
							}
						}
						if(arr[i]!=""){
							if(new_arr.length==0){
								new_arr.push({
										name:arr[i],
										num:num
									})
							}else{
								var exist = false;
								for(var k = 0;k<new_arr.length;k++){
									if(new_arr[k].name==arr[i]){
										exist = true;
									}
								}
								if(!exist){
									new_arr.push({
										name:arr[i],
										num:num
									})
								}
							}
						}
					}
					var final_arr = [];
					for(var i = 0;i<new_arr.length;i++){
						var str = "";
						str = new_arr[i].name.slice(0,-1)+new_arr[i].num;
						final_arr.push(str)
					}
					return final_arr.join(";");
				}
			},
			switchL() {
				return function(text) {
					return L_(text)
				}
			}
//			o_price() {
//				if(this.total_price == this.result.price) {
//					return this.result.o_price
//				} else {
//					return this.numberFixed(Number(this.total_price) + (Number(this.result.o_price) - Number(this.result.price)))
//				}
//			}
		},
		mounted() {
			this.id = this.$route.query.good_id;
			if(common.checkAlipay()) {
				my.postMessage({barname:L_('MT智惠点餐')});
			}
			//			this.id = 53462;
			window.scrollTo(0, 0);
			this.getDetail();
			setTimeout(function() {
				var width = window.screen.availWidth;
				if(document.getElementById("swiper")) {
					document.getElementById("swiper").style.maxHeight = width + "px";
				}
			}, 1000)
		},
		methods: {
			...mapMutations(["add_cart"]),
			initVideo() {
				//初始化视频方法
				let myPlayer = this.$video(myVideo, {
					//确定播放器是否具有用户可以与之交互的控件。没有控件，启动视频播放的唯一方法是使用autoplay属性或通过Player API。
					controls: true,
					//自动播放属性,muted:静音播放
					autoplay: true,
					//建议浏览器是否应在<video>加载元素后立即开始下载视频数据。
					preload: "auto"
				});
			},
			change_less_more_toggle() {
				this.less_more_toggle_flag = !this.less_more_toggle_flag
			},
			closeAd() {
				this.ad_flag = false;
			},
			minus_selected_more(indexA, indexB) {
				var _this = this;
				var temp = this.result;
				this.result = [];
				if(temp.subsidiary_piece[indexA].goods[indexB].order_number<=0){
					this.result = temp;
					return;
				}
				temp.subsidiary_piece[indexA].goods[indexB].order_number--;
				temp.subsidiary_piece[indexA].order_number--;
				temp.subsidiary_piece[indexA].goods[indexB].order_name.pop();
				_this.total_price = Number(_this.total_price) - Number(temp.subsidiary_piece[indexA].goods[indexB].last_price.slice(-1));
				_this.o_price = Number(_this.o_price) + Number(temp.subsidiary_piece[indexA].goods[indexB].last_price.slice(-1));
				temp.subsidiary_piece[indexA].goods[indexB].last_price = temp.subsidiary_piece[indexA].goods[indexB].last_price.slice(0,-1);
				if(temp.subsidiary_piece[indexA].goods[indexB].order_number <= 0) {
					temp.subsidiary_piece[indexA].goods[indexB].selected_more = '';
				}
				this.result = temp;
			},
			add_selected_more(indexA, indexB) {
				if(this.result.subsidiary_piece[indexA].order_number >= this.result.subsidiary_piece[indexA].maxnum && this.result.subsidiary_piece[indexA].maxnum != this.result.subsidiary_piece[indexA].mininum) {
					weui.alert(L_('不能超过') + this.result.subsidiary_piece[indexA].maxnum + L_('份')+'！');
					return
				}
				var temp = this.result;
				var _this = this;
				this.result = [];
				var register = [];
				if(!temp.subsidiary_piece[indexA].goods[indexB].selected_more) {
					temp.subsidiary_piece[indexA].goods[indexB].selected_more = 1;
				} else if(temp.subsidiary_piece[indexA].goods[indexB].selected_more == 1) {
					temp.subsidiary_piece[indexA].goods[indexB].selected_more = 2;
					temp.subsidiary_piece[indexA].goods[indexB].order_number++;
					var sign = "";
					for(var i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].spec_list.length; i++) {
						for(var j = 0; j < temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list.length; j++) {
							if(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].order_number >= 1) {
								register.push(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].id_);
								sign += temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].name + "+";
								temp.subsidiary_piece[indexA].goods[indexB].last_price.push(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].price);
								_this.total_price = Number(_this.total_price) + Number(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].price);
								_this.o_price = Number(_this.o_price) + Number(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].price);
								//								var id = temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].id_

							}
						}
					}
					for(var k in temp.subsidiary_piece[indexA].goods[indexB].list) {

						if(k == register.join('_')) {
							sign += ("$" + temp.subsidiary_piece[indexA].goods[indexB].list[k].price + ";")
						}
					}
					for(var i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].properties_list.length; i++) {
						for(var j = 0; j < temp.subsidiary_piece[indexA].goods[indexB].properties_list[i].val_obj.length; j++) {
							if(temp.subsidiary_piece[indexA].goods[indexB].properties_list[i].val_obj[j].order_number == 1) {
								sign += temp.subsidiary_piece[indexA].goods[indexB].properties_list[i].val_obj[j].name
							}
						}
					}
					var final_sign = "(" + sign + ")x1";
//					if(temp.subsidiary_piece[indexA].goods[indexB].order_name.join('').indexOf(sign)==-1){
//						temp.subsidiary_piece[indexA].goods[indexB].order_name.push(final_sign);						
//					}else{
//						var num = 0;
//						for(var i = 0;i<temp.subsidiary_piece[indexA].goods[indexB].order_name.length;i++){
//							if(temp.subsidiary_piece[indexA].goods[indexB].order_name[i].indexOf(sign)!=-1){
//								num = Number(temp.subsidiary_piece[indexA].goods[indexB].order_name[i].slice(-1))+1;
//								temp.subsidiary_piece[indexA].goods[indexB].order_name[i] = ("(" + sign + ")x" + num);
//							}
//						}
//						temp.subsidiary_piece[indexA].goods[indexB].order_name.splice(temp.subsidiary_piece[indexA].goods[indexB].order_name.indexOf(final_sign),1);
//						final_sign = "(" + sign + ")x" + num;
						temp.subsidiary_piece[indexA].goods[indexB].order_name.push(final_sign);
//					}
					temp.subsidiary_piece[indexA].order_number++;
				} else if(temp.subsidiary_piece[indexA].goods[indexB].selected_more == 2) {
					temp.subsidiary_piece[indexA].goods[indexB].selected_more = 1;
				}
				this.result = temp;
			},
			select_tag(indexA, index) {
				var temp = this.result;
				var _this = this;
				this.result = [];
				for(let i = 0; i < temp.spec_list[indexA].list.length; i++) {
					if(i == index && temp.spec_list[indexA].list[i].order_number == 1) {
						temp.spec_list[indexA].list[i].order_number = 0
						temp.spec_list[indexA].order_number = 0
					} else if(i == index && temp.spec_list[indexA].list[i].order_number == 0) {
						temp.spec_list[indexA].list[i].order_number = 1
						temp.spec_list[indexA].order_number = 1
					} else if(i != index && temp.spec_list[indexA].list[i].order_number == 1) {
						temp.spec_list[indexA].list[i].order_number = 0
					}
				}
				var register = [];
				for(let i = 0; i < temp.spec_list.length; i++) {
					for(let j = 0; j < temp.spec_list[i].list.length; j++) {
						if(temp.spec_list[i].list[j].order_number == 1) {
							register.push(temp.spec_list[i].list[j].id_);
						}
					}
				}
				for(var k in temp.list) {
					if(k == register.join('_')) {
						_this.total_price = Number(temp.list[k].price)
						_this.o_price = Number(temp.list[k].old_price)
					}
				}
				this.result = temp;
			},
			changeSubTag(indexA, indexB, indexC, indexD) {
				var temp = this.result;
				this.result = [];
				if(temp.subsidiary_piece[indexA].goods[indexB].properties_list.length == 0) {
					this.result = temp;
					return
				}
				temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].order_number = 0;
				if(temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].num != 1) {
					for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj.length; i++) {
						if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number == 0) {
							temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number = 1;
						} else if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number == 1) {

							temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number = 0;
						}
						temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].order_number += temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number;
					}
				} else {
					for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj.length; i++) {
						if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number == 0) {
							temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number = 1;
						} else if(temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number == 1) {
							temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number = 0;
						}
						temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].order_number += temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number;
					}
				}
				//				for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj.length; i++) {
				//					if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number == 0) {
				//						temp.subsidiary_piece[indexA].goods[indexB].properties_list[indexC].val_obj[i].order_number = 1;
