				//				}
				this.result = temp;
			},
			changeSubVal(indexA, indexB, indexC, indexD) {
				var temp = this.result;
				var _this = this;
				this.result = [];
				if(temp.subsidiary_piece[indexA].goods[indexB].spec_list.length == 0) {
					this.result = temp;
					return
				}
				for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list.length; i++) {
					if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number == 1) {
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number = 0
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].order_number = 0
					} else if(i == indexD && temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number == 0) {
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number = 1
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].order_number = 1
					} else if(i != indexD && temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number == 1) {
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number = 0
					}
				}
				//				var register = [];
				//				for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].spec_list.length; i++) {
				//					for(let j = 0; j < temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list.length; j++) {
				//						if(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].order_number == 1) {
				//							register.push(temp.subsidiary_piece[indexA].goods[indexB].spec_list[i].list[j].id_);
				//						}
				//					}
				//				}
				//				for(var k in temp.subsidiary_piece[indexA].goods[indexB].list) {
				//					if(k == register.join('_')) {
				//						_this.total_price -= temp.subsidiary_piece[indexA].goods[indexB].last_price;
				//						temp.subsidiary_piece[indexA].goods[indexB].last_price = Number(temp.subsidiary_piece[indexA].goods[indexB].list[k].price)
				//						_this.total_price += temp.subsidiary_piece[indexA].goods[indexB].last_price;
				//					}
				//				}
				for(let i = 0; i < temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list.length; i++) {
					if(i == indexD) {
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number = 1
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].order_number++
					} else {
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].list[i].order_number = 0
						temp.subsidiary_piece[indexA].goods[indexB].spec_list[indexC].order_number--
					}
				}
				this.result = temp;
			},
			select_val(indexA, index) {
				var temp = this.result;
				this.result = [];
				temp.properties_list[indexA].order_number = 0;
				if(temp.properties_list[indexA].num != 1) {
					for(let i = 0; i < temp.properties_list[indexA].val_obj.length; i++) {
						if(i == index && temp.properties_list[indexA].val_obj[i].order_number == 0) {
							temp.properties_list[indexA].val_obj[i].order_number = 1;
						} else if(i == index && temp.properties_list[indexA].val_obj[i].order_number == 1) {
							temp.properties_list[indexA].val_obj[i].order_number = 0;
						}
						temp.properties_list[indexA].order_number += temp.properties_list[indexA].val_obj[i].order_number;
					}
				} else {
					for(let i = 0; i < temp.properties_list[indexA].val_obj.length; i++) {
						if(i == index && temp.properties_list[indexA].val_obj[i].order_number == 0) {
							temp.properties_list[indexA].val_obj[i].order_number = 1;
						} else if(temp.properties_list[indexA].val_obj[i].order_number == 1) {
							temp.properties_list[indexA].val_obj[i].order_number = 0;
						}
						temp.properties_list[indexA].order_number += temp.properties_list[indexA].val_obj[i].order_number;
					}
				}
				this.result = temp;
			},
			toggle_select_area_show(indexA, type) {
				var temp = this.result;
				this.result = [];
				switch(type) {
					case 'spec_list':
						temp.spec_list[indexA].select_area_show = !temp.spec_list[indexA].select_area_show;
						this.result = temp;
						break;
					case 'properties_list':
						temp.properties_list[indexA].select_area_show = !temp.properties_list[indexA].select_area_show;
						this.result = temp;
						break;
					case 'subsidiary_piece':
						temp.subsidiary_piece[indexA].select_area_show = !temp.subsidiary_piece[indexA].select_area_show;
						this.result = temp;
						break;
				}
				//				if(!this.result[indexA].select_area_show) {
				//					this.$set(this.select_kind[indexA], 'select_area_show', true)
				//				} else {
				//					this.select_kind[indexA].select_area_show = !this.select_kind[indexA].select_area_show;
				//				}
			},
			back_to_menu() {
				var _this = this;
				var desc = [];
				if(this.result.is_time_out) {
					weui.alert(L_("该商品不在售卖时间")+"!");
					return
				} else if(this.result.is_sell_out) {
					weui.alert(L_("该商品已售罄")+"!");
					return
				} else if(this.result.stock != -1 && this.order_number >= this.result.stock) {
					weui.alert(L_("商品已达上限")+"!");
					return
				}
				this.uniqueness_number = [];
				this.uniqueness_number.push(this.result.goods_id);
				for(var i = 0; i < _this.result.spec_list.length; i++) {
					if(_this.result.spec_list[i].order_number != 1) {
						weui.alert(L_('规格请至少选择一项')+"!");
						return
					}
					for(var j = 0; j < _this.result.spec_list[i].list.length; j++) {
						if(_this.result.spec_list[i].list[j].order_number == 1) {
							_this.productParams.push({
								type: 'spec',
								name: _this.result.spec_list[i].list[j].name,
								spec_id: _this.result.spec_list[i].id_,
								id: _this.result.spec_list[i].list[j].id_
							})
							desc.push(_this.result.spec_list[i].list[j].name);
							_this.uniqueness_number.push(_this.result.spec_list[i].list[j].id_);
						}
					}
				}
				for(var i = 0; i < _this.result.properties_list.length; i++) {
					var arr = [];
					for(var j = 0; j < _this.result.properties_list[i].val_obj.length; j++) {
						if(_this.result.properties_list[i].val_obj[j].order_number == 1) {
							arr.push({
								id: j,
								list_id: _this.result.properties_list[i].id_,
								name: _this.result.properties_list[i].val_obj[j].name
							})
							desc.push(_this.result.properties_list[i].val_obj[j].name);
						}
					}
					if(_this.result.properties_list[i].order_number >= 1) {
						_this.productParams.push({
							type: 'properties',
							data: arr
						})
						_this.uniqueness_number.push(_this.result.properties_list[i].id_);
						for(var k = 0; k < arr.length; k++) {
							_this.uniqueness_number.push(arr[k].id)
						}
					}
				}
				for(var i = 0; i < _this.result.subsidiary_piece.length; i++) {
					for(var j = 0; j < _this.result.subsidiary_piece[i].goods.length; j++) {
						var sub_params = [];
						var spec_desc = [];
						var properties_desc = [];
						var str_desc = "";
						if(_this.result.subsidiary_piece[i].goods[j].order_number > 0) {
							_this.uniqueness_number.push(_this.result.subsidiary_piece[i].goods[j].goods_id)
							if(_this.result.subsidiary_piece[i].goods[j].spec_list) {
								for(var k = 0; k < _this.result.subsidiary_piece[i].goods[j].spec_list.length; k++) {
									for(var q = 0; q < _this.result.subsidiary_piece[i].goods[j].spec_list[k].list.length; q++) {
										if(_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].order_number == 1) {
											sub_params.push({
												type: 'spec',
												name: _this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].name,
												spec_id: _this.result.subsidiary_piece[i].goods[j].spec_list[k].id_,
												id: _this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].id_
											})
//											spec_desc.push(_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].name);
											_this.uniqueness_number.push(_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].id_);
										}
										var num = 0;
										for(var z = 0 ; z<_this.result.subsidiary_piece[i].goods[j].order_name.length;z++){
											if(_this.result.subsidiary_piece[i].goods[j].order_name[z].indexOf(_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].name)!=-1){
												num++;
											}
										}
										if(num!=0){
											spec_desc.push("("+_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].name+"+$"+_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].price+")x"+num);											
										}
									}
								}
							}
							if(_this.result.subsidiary_piece[i].goods[j].properties_list) {
								for(var k = 0; k < _this.result.subsidiary_piece[i].goods[j].properties_list.length; k++) {
									var arr = [];
									for(var q = 0; q < _this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj.length; q++) {
										if(_this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj[q].order_number == 1) {
											arr.push({
												id: q,
												list_id: _this.result.subsidiary_piece[i].goods[j].properties_list[k].id_,
												name: _this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj[q].name
											})
											properties_desc.push(_this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj[q].name);
										}
									}
									if(_this.result.subsidiary_piece[i].goods[j].properties_list[k].order_number = 1) {
										sub_params.push({
											type: 'properties',
											data: arr
										})
										_this.uniqueness_number.push(_this.result.subsidiary_piece[i].goods[j].properties_list[i].id_);
										for(var k = 0; k < arr.length; k++) {
											_this.uniqueness_number.push(arr[k].id)
										}
									}
								}
							}
							_this.uniqueness_mumber.push({
								productId: _this.result.subsidiary_piece[i].goods[j].goods_id,
								host_goods_id: _this.result.goods_id,
								productName: _this.result.subsidiary_piece[i].goods[j].name,
								productPrice: _this.result.subsidiary_piece[i].goods[j].price,
								count: _this.result.subsidiary_piece[i].goods[j].order_number,
								productParam: sub_params,
								uniqueness_number: ""
							})
							_this.uniqueness_number.push(_this.result.subsidiary_piece[i].goods[j].order_number)
							if(spec_desc.length!=0||properties_desc.length!=0){
								str_desc+="("
							}
							str_desc+=_this.result.subsidiary_piece[i].goods[j].name;
							if(spec_desc.length!=0){
								str_desc += ("("+spec_desc.join(";")+");")
							}
							str_desc+=properties_desc.join(";");
							if(spec_desc.length!=0||properties_desc.length!=0){
								str_desc+=")"
							}
							str_desc+=("x"+_this.result.subsidiary_piece[i].goods[j].order_number)
							desc.push(str_desc)
						}
					}
				}
				for(var i = 0; i < _this.uniqueness_mumber.length; i++) {
					_this.uniqueness_mumber[i].uniqueness_number = _this.uniqueness_number.join("_");
				}
				this.submit_obj = {
					productId: _this.result.goods_id,
					product_id: _this.id,
					host_goods_id: 0,
					productName: _this.result.name,
					product_name: _this.result.name,
					productPrice: Number(_this.total_price),
					product_price: Number(_this.total_price),
					count: _this.order_number,
					order_number: _this.order_number,
					productParam: _this.productParams,
					product_image: _this.result.image,
					desc: desc.join(";"),
					uniqueness_number: _this.uniqueness_number.join("_"),
					uniqueness_mumber: _this.uniqueness_mumber,
					old_price:_this.result.o_price,
					stock:_this.result.stock
				}
				console.log(this.submit_obj)
				try{
					_this.add_cart(_this.submit_obj);					
				}catch(e){
					if(common.checkAlipay()) {
						my.postMessage({
							'sendToMiniProgram': e
						});
					}
				}
				sessionStorage.setItem('cart_flag', false);
				sessionStorage.setItem('back_flag', true);
				localStorage.setItem('foodList', JSON.stringify(_this.foodList));
				localStorage.setItem('cart', JSON.stringify(_this.cart));
				localStorage.setItem('count', JSON.stringify(_this.count));
				localStorage.setItem('totalPrice', JSON.stringify(_this.totalPrice));
				localStorage.setItem('submit_menu', JSON.stringify(_this.submit_menu));
				openWebviewUrl("back")
			},
			add_order_number(indexA, indexB) {
				if(this.result.subsidiary_piece[indexA].order_number >= this.result.subsidiary_piece[indexA].maxnum) {
					weui.alert(L_('最多选择') + this.result.subsidiary_piece[indexA].maxnum + L_('份')+"!");
					return
				}
				var temp = this.result;
				this.result = [];
				temp.subsidiary_piece[indexA].order_number++;
				temp.subsidiary_piece[indexA].goods[indexB].order_number++;
				this.total_price = Number(this.total_price) + Number(temp.subsidiary_piece[indexA].goods[indexB].price);
				this.o_price = Number(this.o_price) + Number(temp.subsidiary_piece[indexA].goods[indexB].price);
				this.result = temp;
			},
			minus_order_number(indexA, indexB) {
				var temp = this.result;
				this.result = [];
				temp.subsidiary_piece[indexA].order_number--;
				temp.subsidiary_piece[indexA].goods[indexB].order_number--;
				this.total_price = Number(this.total_price) - Number(temp.subsidiary_piece[indexA].goods[indexB].price);
				this.o_price = Number(this.o_price) - Number(temp.subsidiary_piece[indexA].goods[indexB].price);
				this.result = temp;
			},
			add_total_order_number() {
				//				var unit_price = Number(this.total_price) / this.order_number;
				if(this.result.is_time_out) {
					weui.alert(L_("该商品不在售卖时间")+"!");
					return
				} else if(this.result.is_sell_out) {
					weui.alert(L_("该商品已售罄"+"!"));
					return
				} else if(this.result.stock != -1 && this.order_number >= this.result.stock) {
					weui.alert(L_("商品已达上限")+"!");
					return
				}
				if(this.order_number<this.result.stock||this.result.stock == -1){
					this.order_number++;					
				}
				//				this.total_price = Number(this.total_price) + unit_price
			},
			minus_total_order_number() {
				if(this.order_number == 1) {
					return
				}
				//				var unit_price = Number(this.total_price) / this.order_number;
				this.order_number--;
				//				this.total_price = Number(this.total_price) - unit_price
			},
			getDetail() {
				var _this = this;
				common.http('Foodshop&a=goods_detail', {
					goods_id: _this.id
				}, function(res) {
					_this.result = res;
					if(res.video_url) {
						_this.initVideo();
					}
					_this.cook = res.cooking_methods.join('/');
					_this.material = res.material.join('/');
					_this.total_price = res.price;
					_this.o_price = Number(res.o_price);
					_this.special_food_materials = res.special_food_materials;
					_this.flavor = res.flavor;
					for(var i = 0; i < res.spec_list.length; i++) {
						_this.result.spec_list[i].select_area_show = true;
						_this.result.spec_list[i].order_number = 0;
						for(var j = 0; j < res.spec_list[i].list.length; j++) {
							_this.result.spec_list[i].list[j].order_number = 0;
							if(j == 0) {
								_this.select_tag(i, 0);
							}
						}
					}
					for(var i = 0; i < res.properties_list.length; i++) {
						_this.result.properties_list[i].select_area_show = true;
						_this.result.properties_list[i].order_number = 0;
						_this.result.properties_list[i].val_obj = [];
						for(var j = 0; j < res.properties_list[i].val_status.length; j++) {
							_this.result.properties_list[i].val_obj.push({
								name: res.properties_list[i].val_status[j][0],
								order_number: 0,
								is_show: _this.result.properties_list[i].val_status[j][1]
							})
						}
						if(_this.result.properties_list[i].num == 1) {
							_this.select_val(i, 0)
						}
					}
					for(var i = 0; i < res.subsidiary_piece.length; i++) {
						_this.result.subsidiary_piece[i].select_area_show = true;
						_this.result.subsidiary_piece[i].order_number = 0;
						for(var j = 0; j < res.subsidiary_piece[i].goods.length; j++) {
							_this.result.subsidiary_piece[i].goods[j].order_number = 0;
							_this.result.subsidiary_piece[i].goods[j].order_name = [];
							_this.result.subsidiary_piece[i].goods[j].last_price = [];
							if(_this.result.subsidiary_piece[i].goods[j].properties_list) {
								for(var k = 0; k < _this.result.subsidiary_piece[i].goods[j].properties_list.length; k++) {
									_this.result.subsidiary_piece[i].goods[j].properties_list[k].order_number = 0;
									_this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj = [];
									for(var q = 0; q < _this.result.subsidiary_piece[i].goods[j].properties_list[k].val_status.length; q++) {
										_this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj.push({
											name: _this.result.subsidiary_piece[i].goods[j].properties_list[k].val_status[q][0],
											order_number: 0,
											is_show: _this.result.subsidiary_piece[i].goods[j].properties_list[k].val_status[q][1]
										})
										if(_this.result.subsidiary_piece[i].goods[j].properties_list[k].num == 1) {
											_this.result.subsidiary_piece[i].goods[j].properties_list[k].val_obj[0].order_number = 1;
										}
									}
								}
							}
							if(_this.result.subsidiary_piece[i].goods[j].spec_list) {
								for(var k = 0; k < _this.result.subsidiary_piece[i].goods[j].spec_list.length; k++) {
									_this.result.subsidiary_piece[i].goods[j].spec_list[k].order_number = 0;
									if(_this.result.subsidiary_piece[i].goods[j].spec_list[k].list.length != 0) {
										for(var q = 0; q < _this.result.subsidiary_piece[i].goods[j].spec_list[k].list.length; q++) {
											_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].order_number = 0;
											for(var ke in _this.result.subsidiary_piece[i].goods[j].list){
												if(ke == _this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].id_){
													_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].price = _this.result.subsidiary_piece[i].goods[j].list[ke].price;
													_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[q].old_price = _this.result.subsidiary_piece[i].goods[j].list[ke].old_price;
												}
											}
											if(q == 0) {
												_this.result.subsidiary_piece[i].goods[j].spec_list[k].list[0].order_number = 1;
											}
										}
									}
								}
							}
						}
					}
					console.log(res)
				}, function(err) {
					weui.alert(err.errMsg)
				}, "post")
			}
		}
	};
</script>

