<template>
	<div class="container">
		<div class="order">
			<span class="HelveticaNeue">{{switchL('您的点餐内容如下，点餐时，可向服务员厨师提供该内容便于快速点餐。您最终需要支付的金额以餐厅提供的金额为准。')}}</span>
			<div class="time_container">
				<span class="order_form HelveticaNeue-Medium">Order Form</span>
				<span class="time">{{submit_menu.order_time}}</span>
			</div>
			<div class="halving_line"></div>
			<div class="order_list" v-for="(item,index) in submit_menu.goods_list" :key="index">
				<div class="order_list_left">
					<span class="order_list_en HelveticaNeue">{{item.name_second}}</span><br />
					<span class="order_list_en order_list_comment" v-if="item.str_second">{{item.str_second}}</span><br  v-if="item.str_second"/>
					<span class="order_list_cn">{{item.name}}</span><br />
					<span class="order_list_cn order_list_cn_comment" v-if="item.str">{{item.str}}</span><br v-if="item.str" />
				</div>
				<span class="order_list_right">${{numberFixed(item.price)}}</span>
			</div>
			<div class="halving_line fix_margin"></div>
			<div class="total_container HelveticaNeue">
				<span class="total_en_name">Subtotal</span>
				<span class="total_cn_name">{{switchL('小计')}}</span>
				<span class="total_number">${{numberFixed(submit_menu.price)}}</span>
			</div>
			<div class="total_container HelveticaNeue">
				<span class="total_en_name">GST</span>
				<span class="total_cn_name">{{switchL('税')}}</span>
				<span class="total_number">${{numberFixed(submit_menu.tax_rate_price)}}</span>
			</div>
			<div class="total_container HelveticaNeue">
				<span class="total_en_name">Total</span>
				<span class="total_en_comment">(inc GST)</span>
				<span class="total_cn_name">{{switchL('总计(包含税)')}}</span>
				<span class="total_number">${{numberFixed(submit_menu.pay_price)}}</span>
			</div>
		</div>
		<div class="back_to_menu" @click="back_to_menu()">{{switchL('返回菜单页')}}</div>
	</div>
</template>

<script>
	import { mapState, mapActions, mapGetters, mapMutations } from 'vuex';
	export default {
		data() {
			return {
				id:0,
				submit_menu:{}
			}
		},
		mounted(){
			var _this = this;
			this.id = this.$route.query.store_id;
			this.submit_menu = JSON.parse(localStorage.submit_menu);
			if(common.checkAlipay()) {
				my.postMessage({barname:L_(_this.submit_menu.cn_name)});
			}
//			if(common.checkAlipay()){
//				my.postMessage({'sendToMiniProgram': localStorage});
//			}
		},
		methods: {
			back_to_menu() {
				openWebviewUrl("back")
			}
		},
		computed:{
//			...mapState(["submit_menu"]),
			numberFixed(){
				return function(num){
					return Number(num).toFixed(2);
				}
			},
			switchL() {
				return function(text) {
					return L_(text)
				}
			}
		}
	}
</script>

<style scoped="scoped">
	.HelveticaNeue {
		font-family: 'HelveticaNeue';
	}
	
	.HelveticaNeue-Medium {
		font-family: 'HelveticaNeue-Medium';
	}
	
	.container {
		background: url("./img/submit_bgImg.png") no-repeat top;
		background-size: contain;
		padding-top: 244px;
		text-align: left;
	}
	
	.container .order {
		width: 616px;
		padding: 36px;
		margin: 0 auto;
		box-shadow: 0 6px 12px 0px rgb(0, 0, 0, 0.16);
		z-index: 99;
		background-color: rgb(255, 255, 255);
		margin-bottom: 200px;
	}
	
	.container .order span {
		font-size: 24px;
	}
	.container .order .time_container{
		margin-top: 50px;
		height: 56px;
		line-height: 56px;
	}
	.container .order .time_container .order_form{
		font-size: 36px;
		font-weight: 600;
	}
	.container .order .time_container .time{
		font-size: 24px;
		float: right;
	}
	.container .order .halving_line{
		width: 100%;
		height: 2px;
		margin-top: 20px;
		background-color: rgb(0,0,0);
	}
	.container .order .order_list{
		position: relative;
	}
	.container .order .fix_margin{
		margin-top: 30px;
	}
	.container .order .order_list .order_list_left{
		margin-top: 27px;
		width: 480px;
	}
	.container .order .order_list .order_list_left span{
		display: inline-block;
	}
	.container .order .order_list .order_list_left .order_list_en{
		font-size: 28px;
		font-weight: 600;
	}
	.container .order .order_list .order_list_left .order_list_comment{
		font-size: 18px;
		margin-top: 2px;
	}
	.container .order .order_list .order_list_left .order_list_cn{
		font-size: 22px;
		color: rgb(112,112,112);
		margin-top: 6px;
	}
	.container .order .order_list .order_list_left .order_list_cn_comment{
		font-size: 16px;
		color: rgb(132,132,132);
		margin-top: 4px;
	}
	.container .order .order_list .order_list_right{
		position: absolute;
		top: 6px;
		right: 16px;
		font-size: 28px;
		font-weight: 600;
	}
	.container .order .total_container{
		margin-top: 3px;
		height: 28px;
		line-height: 28px;
		margin-top: 12px;
		position: relative;
	}
	.container .order .total_container span{
		display: inline-block;
	}
	.container .order .total_container .total_en_name,
	.container .order .total_container .total_en_comment,
	.container .order .total_container .total_number{
		font-size: 24px;
		font-weight: 600;
	}
	.container .order .total_container .total_en_comment{
		font-size: 16px;
	}
	.container .order .total_container .total_number{
		float: right;
	}
	.container .order .total_container .total_cn_name{
		position: absolute;
		right: 100px;
		font-size: 16px;
		color: rgb(132,132,132);
	}
	.container .back_to_menu{
		width: 278px;
		height: 77.4px;
		position: fixed;
		left: 0;
		right: 0;
		bottom: 48px;
		background-color: rgb(92,198,204);
		line-height: 77.4px;
		color: rgb(255,255,255);
		border-radius: 110px;
		text-align: center;
		margin: 0 auto;
	}
</style>


