import Vue from 'vue'
import Vuex from 'vuex'

Vue.use(Vuex)

let defaultFoodList = {};
let defaultCart = [];
let defaultCount = 0;
let defaultTotalPrice = 0;
let defaultSubmitMenu = {};
try {
	if(localStorage.length > 0 && localStorage.foodList) {
		defaultFoodList = JSON.parse(localStorage.foodList);
		defaultCart = JSON.parse(localStorage.cart);
		defaultCount = Number(JSON.parse(localStorage.count));
		defaultTotalPrice = Number(JSON.parse(localStorage.totalPrice));
		defaultSubmitMenu = JSON.parse(localStorage.submit_menu);
	}
} catch(e) {}

const state = {
	foodList: defaultFoodList,
	cart: defaultCart,
	count: defaultCount,
	totalPrice: defaultTotalPrice,
	specialDiscountList: [],
	submit_menu: defaultSubmitMenu
}

const getters = {
	foodListChange(state) {
		state.count = state.count;
		return state.foodList.product_list;
	}
}

const mutations = {
	addFood(state, params) {
		state.count++;
		let exist = false;
		let indexc = 0;
		for(let i = 0; i < state.cart.length; i++) {
			if(state.cart[i].product_id == params.id && (state.cart[i].order_number < state.cart[i].stock || state.cart[i].stock == -1)) {
				//				if(!JSON.parse(sessionStorage.getItem('back_flag'))) {
				//					state.foodList.product_list[params.index].product_list[params.subIndex].order_number++;
				//				}
				state.cart[i].order_number++;
				exist = true;
				indexc = i;
			} else if(state.cart[i].product_id == params.id && state.cart[i].order_number >= state.cart[i].stock && state.cart[i].stock != -1) {
				state.count--;
				return
			}
		}
		if(!exist) {
			state.foodList.product_list[params.index].product_list[params.subIndex].order_number += 1;
			state.cart.push(state.foodList.product_list[params.index].product_list[params.subIndex]);
		}
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.id && (state.foodList.product_list[i].product_list[j].order_number < state.foodList.product_list[i].product_list[j].stock || state.foodList.product_list[i].product_list[j].stock == -1)) {
					state.foodList.product_list[i].product_list[j].order_number = state.cart[indexc].order_number;
				}
			}
		}
		state.foodList.product_list[params.index].order_number++;
		state.totalPrice = Number(state.totalPrice) + Number(state.foodList.product_list[params.index].product_list[params.subIndex].product_price);
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	minusFood(state, params) {
		state.count--;
		let index = 0;
		for(let i = 0; i < state.cart.length; i++) {
			if(state.cart[i].product_id == params.id && state.cart[i].uniqueness_number) {
				index = i;
				state.cart[index].order_number -= 1;
			} else if(state.cart[i].product_id == params.id && !state.cart[i].uniqueness_number) {
				index = i;
			}
			//			else if(state.cart[i].product_id == params.id &&state.foodList.product_list[params.index].product_list[params.subIndex].uniqueness_number){
			//				index = i;
			//				state.cart[index].order_number -= 1;
			//				console.log(state.foodList.product_list[params.index].product_list[params.subIndex])
			//			}
		}
		var x = 0,
			y = 0;
		state.totalPrice = Number(state.totalPrice) - Number(state.cart[index].product_price)
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.id && state.foodList.product_list[i].product_list[j].order_number == 1) {
					state.foodList.product_list[i].product_list[j].order_number = 0;
					state.foodList.product_list[i].order_number = 0
				} else if(state.foodList.product_list[i].product_list[j].product_id == params.id && state.foodList.product_list[i].product_list[j].order_number > 0) {
					state.foodList.product_list[i].product_list[j].order_number -= 1;
					state.foodList.product_list[i].order_number--
				}
			}
		}
		if(state.cart[index].order_number <= 0) {
			state.cart.splice(index, 1);
		}
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	addCartFood(state, params) {
		console.log('addCartFood')
		state.count++;
		//		if(JSON.parse(sessionStorage.getItem('back_flag'))) {
		state.cart[params.index].order_number++;
		//			console.log(state.cart[params.index])
		//		}
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.id && (state.foodList.product_list[i].product_list[j].order_number < state.foodList.product_list[i].product_list[j].stock || state.foodList.product_list[i].product_list[j].stock == -1)) {
					//					console.log(JSON.parse(sessionStorage.getItem('back_flag')))
					//					if(JSON.parse(sessionStorage.getItem('back_flag'))) {
					//						console.log('进来了')
					if(state.cart[params.index].uniqueness_number){
						state.foodList.product_list[i].product_list[j].order_number++;
					}else{
						state.foodList.product_list[i].product_list[j].order_number = state.cart[params.index].order_number;						
					}
					//					}
					state.foodList.product_list[i].order_number++;
				} else if(state.foodList.product_list[i].product_list[j].product_id == params.id && state.foodList.product_list[i].product_list[j].order_number >= state.foodList.product_list[i].product_list[j].stock && state.foodList.product_list[i].product_list[j].stock != -1) {
					state.count--;
					//					if(JSON.parse(sessionStorage.getItem('back_flag'))) {
					state.cart[i].order_number--;
					//					}
					return
				}
			}
		}
		state.totalPrice = Number(state.totalPrice) + Number(state.cart[params.index].product_price);
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	minusCartFood(state, params) {
		state.count--;
		if(state.cart[params.index].order_number>0){
			state.cart[params.index].order_number--;			
		}
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.id&&state.foodList.product_list[i].product_list[j].order_number >0) {
					if(state.cart[params.index].uniqueness_number){
						state.foodList.product_list[i].product_list[j].order_number--;
					}else{
						state.foodList.product_list[i].product_list[j].order_number = state.cart[params.index].order_number;						
					}
					state.foodList.product_list[i].order_number--;
				}else if(state.foodList.product_list[i].product_list[j].product_id == params.id&&state.foodList.product_list[i].product_list[j].order_number <=0){
					state.foodList.product_list[i].product_list[j].order_number =0;
					state.foodList.product_list[i].order_number=0;
				}
			}
		}
		state.totalPrice = Number(state.totalPrice) - Number(state.cart[params.index].product_price);
		if(state.cart[params.index].order_number <= 0) {
			state.cart.splice(params.index, 1)
		}
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	addHotFood(state, params) {
		let exits = false;
		let index = 0;
		state.count++;
		for(let k = 0; k < state.cart.length; k++) {
			if(state.cart[k].product_id == params.product_id && (state.cart[k].order_number < state.cart[k].stock || state.cart[k].stock == -1)) {
				state.cart[k].order_number++;
				index = k;
				exits = true;
			} else if(state.cart[k].product_id == params.product_id && state.cart[k].order_number >= state.cart[k].stock && state.cart[k].stock != -1) {
				state.count--;
				return
			}
		}
		if(exits == false) {
			if(!params.order_number) {
				params.order_number = 0;
			}
			params.order_number++;
			state.cart.push(params)
		}
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.product_id) {
					if(!state.foodList.product_list[i].product_list[j].order_number) {
						state.foodList.product_list[i].product_list[j].order_number = 0;
						state.foodList.product_list[i].order_number = 0;
					}
					state.foodList.product_list[i].product_list[j].order_number = state.cart[index].order_number;
					state.foodList.product_list[i].order_number++;
				}
			}
		}
		state.totalPrice = Number(state.totalPrice) + Number(params.product_price);
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	getFoodList(state, obj) {
		state.foodList = obj;
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
	},
	getSpecialDiscountList(state, obj) {
		state.specialDiscountList = obj;
	},
	getSubmitMenu(state, obj) {
		state.submit_menu = obj;
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	add_cart(state, params) {
		state.count += params.count;
		var exist = false;
		let index = 0;
		for(let i = 0; i < state.cart.length; i++) {
			if(state.cart[i].product_id == params.productId && state.cart[i].uniqueness_number == params.uniqueness_number&&state.cart[i].uniqueness_number) {
				state.cart[i].order_number += params.count;
				index = i;
				exist = true;
			}else if(state.cart[i].product_id == params.productId&&!state.cart[i].uniqueness_number){
				state.cart[i].order_number += params.count;
				index = i;
				exist = true;
			}
		}
		if(!exist||state.cart.length==0) {
			state.cart.push(params);
			index = state.cart.length - 1;
		}
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				if(state.foodList.product_list[i].product_list[j].product_id == params.productId && (state.foodList.product_list[i].product_list[j].order_number < state.foodList.product_list[i].product_list[j].stock || state.foodList.product_list[i].product_list[j].stock == -1)) {
					if(state.cart[index].uniqueness_number){
						state.foodList.product_list[i].product_list[j].order_number += params.count;
					}
					state.foodList.product_list[i].order_number += params.count;
				} else if(state.foodList.product_list[i].product_list[j].product_id == params.product_id && state.foodList.product_list[i].product_list[j].order_number >= state.foodList.product_list[i].product_list[j].stock && state.foodList.product_list[i].product_list[j].stock != -1) {
					state.count -= params.count;
					state.cart[index].order_number -= params.count;
					if(state.cart[index].order_number <= 0) {
						state.cart.pop();
					}
					return
				}
			}
		}
		state.totalPrice = Number(state.totalPrice) + (Number(params.productPrice) * Number(params.count));
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	clearFood(state, params) {
		state.cart = [];
		state.count = 0;
		state.totalPrice = 0;
		for(let i = 0; i < state.foodList.product_list.length; i++) {
			for(let j = 0; j < state.foodList.product_list[i].product_list.length; j++) {
				state.foodList.product_list[i].product_list[j].order_number = 0;
				state.foodList.product_list[i].order_number = 0;
			}
		}
		localStorage.setItem('foodList', JSON.stringify(state.foodList));
		localStorage.setItem('cart', JSON.stringify(state.cart));
		localStorage.setItem('count', JSON.stringify(state.count));
		localStorage.setItem('totalPrice', JSON.stringify(state.totalPrice));
		localStorage.setItem('submit_menu', JSON.stringify(state.submit_menu));
	},
	refreshList(state, parsms) {
		try {
			if(localStorage.length > 0 && localStorage.foodList) {
				state.foodList = JSON.parse(localStorage.foodList);
				state.cart = JSON.parse(localStorage.cart);
				state.count = Number(JSON.parse(localStorage.count));
				state.totalPrice = Number(JSON.parse(localStorage.totalPrice));
				state.submit_menu = JSON.parse(localStorage.submit_menu);
			}
		} catch(e) {}
	}
}

const actions = {
	addFood({
		commit
	}, params) {
		setTimeout(() => {
			commit('addFood', params)
		}, 100)
	},
	getFoodList({
		commit
	}, params) {
		setTimeout(() => {
			commit('getFoodList', params)
		}, 100)
	},
	getSubmitMenu({
		commit
	}, params) {
		setTimeout(() => {
			commit('getSubmitMenu', params)
		}, 100)
	},
	getSpecialDiscountList({
		commit
	}, params) {
		setTimeout(() => {
			commit('getSpecialDiscountList', params)
		}, 100)
	},
	refreshList({
		commit
	}, params) {
		setTimeout(() => {
			commit('refreshList', params)
		}, 100)
	}
}

const store = new Vuex.Store({
	state,
	getters,
	mutations,
	actions
})

export default store


