<template>
	<div class="container">
		<!--<div class="loading" v-if="loading_flag"><img src="./img/loading.gif" alt="" /></div>-->
		<div class="header">
			<div class="notice-board">
				<div class="header-top">
					<div class="left" v-if="result.image">
						<img :src="result.image" alt="" />
					</div>
					<div :class="result.image?'right':'right right_full'">
						<span class="title">{{result.name}}</span><br />
						<span class="introduction"><span v-if="result.store_notice">{{switchL('公告')}}: </span>{{switchL(result.store_notice)}}</span>
					</div>
				</div>
				<div class="header-bottom">
					<div class="left">
						<div v-for="(item,index) in result.coupon_list_simple" class="tags" :key="'coup'+index">{{item.text}}</div>
					</div>
					<img src="./img/noun_down_1247052.png" alt="" @click="changeHeaderDropShow" />
				</div>
			</div>
		</div>
		<div class="firstBanner" v-if="ad_show&&banner_list.length!=0">
			<img src="./img/advertise_sign.png" alt="" class="ad" />
			<div class="delete" @click="remove_ad"></div>
			<swiper :options="swiperOption1">
				<swiper-slide v-for="(item,index) in result.banner_list" :key="'banner_list'+index">
					<a :href="item.url"><img :src="item.pic" alt="" /></a>
				</swiper-slide>
				<!--<div class="swiper-pagination" slot="pagination"></div>-->
			</swiper>
		</div>
		<span class="subTitle" v-if="preferential.good_count!=0">{{preferential.name}}</span>
		<div class="secondBanner">
			<!--<swiper :options="swiperOption2">-->
			<!--<swiper-slide v-for="item in banner_second" :key="item.index">-->
			<div v-for="(item,index) in preferential.good_list" :key="'index'+index" class="second_bannner_container" v-if="preferential.good_count!=0" @click="jump(item.goods_id)">
				<el-card :body-style="{ padding: '0px' }">
					<img :src="item.product_image" class="card_image"><br />
					<span class="card_title">{{item.name}}</span><br />
					<span class="card_introduction">{{item.describe}}</span><br />
					<div class="card_left">
						<div v-for="(items,index_two) in item.special_food_materials" :key="'index_two'+index_two" class="card_tags orange">
							<img src="./img/orange_tags.png" alt="" class="orangeIcon" /> {{items}}
						</div>
						<div v-for="(items,index_three) in item.flavor" :key="index_three" class="card_tags" :index="'index_three'+index_three">
							{{items}}
						</div>
					</div>
					<div class="price_container">
						<div :class="item.price!=item.old_price?'orange_price now_price':'now_price'">${{numberFixed(item.price)}}</div>
						<div v-if="item.price!=item.old_price" class="past_price">${{numberFixed(item.old_price)}}</div>
					</div>
					<el-button type="success" round @click.stop="addHotFood(item)" v-if="!item.is_sell_out&&!item.is_time_out">{{switchL('加入购物车')}}</el-button>
					<span class="max" v-if="item.is_sell_out&&!item.is_time_out">{{switchL('已售罄')}}</span>
					<span class="max" v-if="item.is_time_out">{{switchL('不在售卖时间')}}</span>
				</el-card>
			</div>
			<!--</swiper-slide>-->
			<!--</swiper>-->
		</div>
		<span class="subTitle">{{switchL('本店菜单')}}</span>
		<Menu style="margin-top: 36px;" ref="Menu" :isFixed="isFixed" :result="result.product_list" v-if="flag"></Menu>
		<el-footer>
			<el-button :class="[{'submit_button_fix':cart.length==0&&cart},'submit_button']" @click="submit()">{{switchL('立即下单')}}</el-button>
			<div class="footer-container" @click="changeDropShow">
				<div class="shopping_cart_circle">
					<img src="./img/shopping_cart.png" alt="" />
					<div class="count_sign" v-if="count>0">{{count}}</div>
				</div>
				<span>${{numberFixed(totalPrice)}}</span>
			</div>
		</el-footer>
		<div class="backdrop" v-if="drop_show" @touchmove.prevent @click="changeDropShow">
			<div class="cart_container" @click.prevent="changeDropShow">
				<div class="cart_title">
					<span class="cart_title_one">{{switchL('已选商品')}}</span>
					<div class="cart_clear" @click="preClearFood()">
						<img src="./img/cart_empty.png" alt="" />
						<span>{{switchL('清空购物车')}}</span>
					</div>
				</div>
				<div v-for="(item,index) in cart" :key="'cart'+index" class="cart_list">
					<img :src="item.product_image" alt="" />
					<div class="cart_textarea">
						<span class="cart_textarea_title">{{item.product_name}}</span><br />
						<span class="cart_textarea_introduction" v-if="item.product_describe">{{item.product_describe}}</span>
						<span class="cart_textarea_introduction" v-if="item.desc">{{item.desc}}</span>
					</div>
					<div class="cart_price">
						<span :class="[{'cart_now_price_fix_color':item.now_price==item.old_price},'cart_now_price']">${{numberFixed(item.product_price)}}</span>
						<span class="cart_past_price" v-if="item.now_price!=item.old_price">${{numberFixed(item.old_price)}}</span>
					</div>
					<div class="cart_order_number">
						<div class="minus" @click="preMinusCartFood({index:index,id:item.product_id})"></div>
						<span>{{item.order_number}}</span>
						<div class="add" @click="addCartFood({index:index,id:item.product_id})"></div>
					</div>
				</div>
			</div>
		</div>
		<div class="backdrop header_backdrop" v-show="header_drop_show" @touchmove.prevent @click="changeHeaderDropShow">
			<div class="header_backdrop_container" @click.prevent="changeHeaderDropShow">
				<div class="header_backdrop_top">
					<img :src="result.image" alt="" />
					<span>{{result.name}}</span>
				</div>
				<div class="header_backdrop_middle">
					<div v-for="(item,index) in result.coupon_list_simple" :key="'coupon_list'+index" class="discount_information">
						<div :class="[{'discount_minus':item.reduction_type=='manjian'},{'discount_discount':item.reduction_type=='zhekou'},'discount']" v-if="item.reduction_type">{{switchL(type(item.reduction_type))}}</div>
						<span>{{item.text}}</span>
					</div>
				</div>
				<div class="header_backdrop_bottom" v-if="result.store_notice">
					<span>{{switchL('公告')}}：</span><br />
					<span>{{result.store_notice}}</span>
				</div>
				<img src='./img/up_arrow.png' @click="changeHeaderDropShow" class="header_backdrop_arrow" />
			</div>
		</div>
	</div>
</template>

<script>
	import "swiper/dist/css/swiper.css";
	import { swiper, swiperSlide } from "vue-awesome-swiper";
	import Menu from '../Menu/Menu'
	//	import L_ from '../../components/L_'
	import { mapState, mapActions, mapGetters, mapMutations } from 'vuex';
	export default {
		name: 'Home',
		data() {
			return {
				flag: false,
				preferential: {},
				result: {},
				store_id: 0,
				isFixed: false,
				ad_show: true,
				drop_show: false,
				header_drop_show: false,
				submit_obj: [],
				swiperOption1: {
					autoplay: true,
					slidesPerView: 'auto',
					spaceBetween: -8,
					pagination: {
						el: '.swiper-pagination',
						clickable: true
					}
				},
				swiperOption2: {
					slidesPerView: 'auto',
					spaceBetween: 0,
					pagination: {
						el: '.swiper-pagination',
						clickable: true
					}
				},
				total: 0.00,
				banner_list: [],
				loading_flag: true
			}
		},
		components: {
			swiper,
			swiperSlide,
			Menu
		},
		computed: {
			...mapState(["count", "totalPrice", "cart", "foodList", "submit_menu"]),
			numberFixed() {
				return function(num) {
					return Number(num).toFixed(2);
				}
			},
			type() {
				return function(reduction_type) {
					if(reduction_type == 'manjian') {
						return "减"
					} else if(reduction_type == 'zhekou') {
						return "折"
					}
				}
			},
			switchL() {
				return function(text) {
					return L_(text)
				}
			}
		},
		mounted() {
			load_config(function(){
				console.log('load config')
				replace_html_lang();
			},false)
			if(common.checkAlipay()) {
				my.postMessage({barname:L_('MT智惠点餐')});
			}
			var _this = this;
			window.addEventListener('scroll', this.onScroll);
			sessionStorage.setItem('back_flag', false);
			this.getSpecialDiscountList(this.banner_second);
			this.store_id = this.$route.query.store_id || 2;
			common.http('Foodshop&a=menu', {
				store_id: _this.store_id
			}, function(res) {
				if(localStorage.length > 0 && localStorage.foodList) {
					_this.result = JSON.parse(localStorage.foodList);
				} else {
					_this.result = res;
					for(var i = 0; i < _this.result.product_list.length; i++) {
						_this.result.product_list[i].order_number = 0;
						for(var j = 0; j < _this.result.product_list[i].product_list.length; j++) {
							_this.result.product_list[i].product_list[j].order_number = 0;
						}
					}
				}
				_this.preferential = _this.result.shop_preferential;
				_this.getFoodList(_this.result);
				_this.flag = true;
				_this.banner_list = _this.result.banner_list;
				_this.loading_flag = false;
			}, function(err) {
				weui.alert(err.errorMsg)
			}, "post")
			//			load_config(function(){
			//				console.log(111)
			//			},false);
			//			console.log(this.$route.query.scrollTop)
			//			this.drop_show = this.$route.query.cart_flag || false;

		},
		methods: {
			...mapMutations(["addCartFood", "minusCartFood", "addHotFood", "clearFood"]),
			...mapActions(['getSpecialDiscountList', "getFoodList", "getSubmitMenu", "refreshList"]),
			remove_ad() {
				this.ad_show = false;
			},
			changeDropShow() {
				if(this.cart.length <= 0) {
					return
				}
				this.drop_show = !this.drop_show;
				sessionStorage.setItem('cart_flag', false);
			},
			changeHeaderDropShow() {
				this.header_drop_show = !this.header_drop_show;
			},
			onScroll() {
				this.scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop
				var offsetTop = this.$refs.Menu.$el.offsetTop
				if(this.scrollTop > offsetTop) {
					this.isFixed = true
				} else {
					this.isFixed = false
				}
			},
			preMinusCartFood(params) {
				this.minusCartFood(params)
				if(this.cart.length <= 0) {
					this.drop_show = false;
				}
			},
			jump(id) {
				if(common.checkAlipay()) {
					my.postMessage({
						'sendToMiniProgram': '已加载'
					});
				}
				//				this.$router.push({
				//					path: '/details',
				//					query: {
				//						good_id: id
				//					}
				//				})
				openWebviewUrl("/packapp/foodshop/#/details?good_id=" + id);
			},
			submit() {
				var _this = this;
				this.submit_obj = [];
				if(this.cart.length == 0) {
					return
				}
				for(var i = 0; i < _this.cart.length; i++) {
					//					if(!_this.cart[i].uniqueness_mumber){
					_this.submit_obj.push({
						productId: _this.cart[i].product_id,
						productName: _this.cart[i].product_name,
						productPrice: _this.cart[i].product_price,
						count: _this.cart[i].order_number,
						productParam: _this.cart[i].productParam,
						host_goods_id: _this.cart[i].host_goods_id || 0,
						uniqueness_number: _this.cart[i].uniqueness_number || _this.cart[i].product_id
					})
					if(_this.cart[i].uniqueness_mumber) {
						for(var j = 0; j < _this.cart[i].uniqueness_mumber.length; j++) {
							_this.submit_obj.push({
								productId: _this.cart[i].uniqueness_mumber[j].productId,
								productName: _this.cart[i].uniqueness_mumber[j].productName,
								productPrice: _this.cart[i].uniqueness_mumber[j].productPrice,
								count: _this.cart[i].uniqueness_mumber[j].count,
								productParam: _this.cart[i].uniqueness_mumber[j].productParam,
								host_goods_id: _this.cart[i].uniqueness_mumber[j].host_goods_id,
								uniqueness_number: _this.cart[i].uniqueness_mumber[j].uniqueness_number
							})
						}
					}
					//					}
				}
				console.log(_this.submit_obj)
				common.http('Foodshop&a=ajax_cart', {
					store_id: _this.store_id,
					productCart: _this.submit_obj
				}, function(res) {
					sessionStorage.setItem('cart_flag', false);
					localStorage.setItem('foodList', JSON.stringify(_this.result));
					localStorage.setItem('cart', JSON.stringify(_this.cart));
					localStorage.setItem('count', JSON.stringify(_this.count));
					localStorage.setItem('totalPrice', JSON.stringify(_this.totalPrice));
					_this.getSubmitMenu(res)
					setTimeout(function() {
						localStorage.setItem('submit_menu', JSON.stringify(_this.submit_menu));
						openWebviewUrl("/packapp/foodshop/#/submit?store_id=" + _this.store_id);
						//						if(common.checkAlipay()) {
						//							my.postMessage({
						//								'sendToMiniProgram': localStorage
						//							});
						//						}
					}, 500)
					//					_this.$router.push({
					//						path: '/submit',
					//						query:{store_id:_this.store_id}
					//					})
					console.log(res)
				}, function(err) {
					weui.alert(err.errorMsg)
				}, "post")
			},
			preClearFood() {
				var _this = this;
				weui.confirm(L_("是否清空购物车？"), function() {
					_this.clearFood();
					_this.drop_show = false;
					localStorage.setItem('foodList', JSON.stringify(_this.foodList));
					localStorage.setItem('cart', JSON.stringify(_this.cart));
					localStorage.setItem('count', JSON.stringify(_this.count));
					localStorage.setItem('totalPrice', JSON.stringify(_this.totalPrice));
					localStorage.setItem('submit_menu', JSON.stringify(_this.submit_menu));
				}, function() {
					_this.drop_show = false;
				})
			}
		},
		destroyed() {
			window.removeEventListener('scroll', this.onScroll);
		},
		activated() {
			var _this = this;
			this.drop_show = JSON.parse(sessionStorage.getItem('cart_flag'));
			if(common.checkAlipay()) {
				my.onMessage = function(e) {
					if(e && e.foodshop_reload_cart) {
						_this.refreshList();
					}
				}
				my.postMessage({barname:L_('MT智惠点餐')});
			}
		}
	}
</script>

