<template>
	<el-container>
		<el-aside :class="isFixed?'isFixed':''">
			<div v-for="(item,index) in foodListChange" :key="index" @click.stop="changeVarieties(index,item.cat_name)" :class="index==current_varieties?'varieties active':'varieties'">
				<div class="varieties_pic" v-if="item.spec_cat_id=='cat_hot'">
					<img src="./img/menu_hot.png" alt="" />
				</div>
				<div class="varieties_pic" v-if="item.spec_cat_id=='cat_discount'">
					<img src="./img/menu_discount.png" alt="" />
				</div>
				<div class="order_number" v-if="item.order_number>0">{{item.order_number}}</div>
				{{item.cat_name}}
			</div>
		</el-aside>
		<el-aside v-if="isFixed"></el-aside>
		<el-main>
			<!--<div v-for="(item,index) in foodListChange" :key="'index'+index" :class="index==current_varieties?'food_varieties_group food_varieties_group_fixed':'food_varieties_group'" :id="item.cat_name">-->
			<div v-for="(item,index) in foodListChange" :key="'index'+index" class="food_varieties_group" :id="item.cat_name">
				<div class="food_varieties">{{item.cat_name}}<span v-if="item.desc">({{item.desc}})</span></div>
				<div v-for="(item_two,subIndex) in item.product_list" :key="'subIndex'+subIndex" :index="subIndex" class="food" @click="jump(item_two.product_id)">
					<img v-if="item_two.product_image" :src="item_two.product_image" alt="" />
					<div :class="item_two.product_image?'right':'right right_full'">
						<span :class="item_two.spicy?'card_title_fixed card_title':'card_title'">{{item_two.product_name}}</span><img src="./img/pepper.png" alt="" class="pepper" v-if="item_two.spicy" /><br />
						<span class="card_introduction" v-if="item_two.product_describe">{{item_two.product_describe}}</span>
						<div class="card_left" v-if="item_two.special_food_materials||item_two.flavor">
							<div v-for="(item_three,index_three) in item_two.special_food_materials" :key="'index_three'+index_three" class="card_tags orange" :index="index_three">
								<img src='./img/orange_tags.png' class="orangeIcon" /> {{item_three}}
							</div>
							<div v-for="(item_four,index_four) in item_two.flavor" :key="'index_four'+index_four" class="card_tags" :index="index_four">
								{{item_four}}
							</div>
						</div>
						<div class="now_price_container">
							<div :class="item_two.product_price!=item_two.old_price?'orange_price now_price':'now_price'">${{numberFixed(item_two.product_price)}}</div>
							<div v-if="item_two.product_price!=item_two.old_price" class="past_price">${{numberFixed(item_two.old_price)}}</div>
						</div>
						<span class="max" v-if="item_two.order_number>=item_two.stock&&item_two.stock!=-1&&!item_two.is_sell_out&&!item_two.is_time_out">{{switchL('已达上限')}}</span>
						<span class="choose" v-if="(item_two.has_spec||item_two.has_format||item_two.is_subsidiary_goods!='0')&&!item_two.is_sell_out&&!item_two.is_time_out&&item_two.order_number==0">{{switchL('选规格')}}</span>
						<img src="./img/menu_add.png" alt="" class="icon_add" @click.stop.prevent="add_Food({index:index,subIndex:subIndex,id:item_two.product_id},item_two)" v-if="!item_two.is_sell_out&&!item_two.is_time_out&&((!item_two.has_spec&&!item_two.has_format&&item_two.is_subsidiary_goods=='0')||item_two.order_number>0)" />
						<span class="food_order_number_add" v-if="!item_two.is_sell_out&&!item_two.is_time_out&&item_two.order_number>0">{{item_two.order_number}}</span>
						<img src="./img/menu_minus.png" alt="" class="icon_minus" v-if="item_two.order_number>0&&!item_two.is_sell_out&&!item_two.is_time_out" @click.stop.prevent="minusFood({index:index,subIndex:subIndex,id:item_two.product_id})" />
						<span class="max max_fix" v-if="item_two.is_sell_out&&!item_two.is_time_out">{{switchL('已售罄')}}</span>
						<span class="max max_fix" v-if="item_two.is_time_out">{{switchL('不在售卖时间')}}</span>
					</div>
				</div>
			</div>
		</el-main>
	</el-container>
</template>

<script>
	import { mapState, mapActions, mapGetters, mapMutations } from 'vuex';
	export default {
		props: ["isFixed", "result"],
		name: 'Menu',
		data() {
			return {
				//				varieties:{},
				current_varieties: 0,
				varieties_arr: document.getElementsByClassName("food_varieties_group")
			}
		},
		methods: {
			...mapMutations(["minusFood", "clearFood"]),
			...mapActions(["addFood", "clearFood"]),
			add_Food(params, obj) {
				if(obj.has_spec || obj.has_format) {
//					this.$router.push({
//						path: '/details',
//						query: {
//							good_id: obj.product_id
//						}
//					})
					openWebviewUrl("/packapp/foodshop/#/details?good_id="+obj.product_id);
				}else{
					this.addFood(params);
				}
			},
			changeVarieties(index, id) {
				this.current_varieties = index;
//								this.onScrollMenu();
				document.querySelector("#" + id).scrollIntoView(true);
				for(let i = 0; i < this.varieties_arr.length - 1; i++) {
					if(i == index){
						document.getElementsByClassName("food_varieties")[i].setAttribute('class', 'food_varieties food_varieties_fixed');
						document.getElementsByClassName("food_varieties_group")[i].setAttribute('class', 'food_varieties_group food_varieties_group_fixed');
					}else{
						document.getElementsByClassName("food_varieties")[i].setAttribute('class', 'food_varieties');
						document.getElementsByClassName("food_varieties_group")[i].setAttribute('class', 'food_varieties_group');						
					}
				}
				window.removeEventListener('scroll', this.onScrollMenu);
				var _that = this;
				setTimeout(function() {
					window.addEventListener('scroll', _that.onScrollMenu);
				}, 100)
			},
			onScrollMenu() {
				var scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop
				var temp = 0;
				for(let i = 0; i < this.varieties_arr.length - 1; i++) {
//					if( this.varieties_arr[i].offsetTop >= scrollTop) {
						document.getElementsByClassName("food_varieties")[i].setAttribute('class', 'food_varieties');
						document.getElementsByClassName("food_varieties_group")[i].setAttribute('class', 'food_varieties_group');
					if( this.varieties_arr[i].offsetTop < scrollTop) {
						document.getElementsByClassName("food_varieties")[i].setAttribute('class', 'food_varieties food_varieties_fixed');
						document.getElementsByClassName("food_varieties_group")[i].setAttribute('class', 'food_varieties_group food_varieties_group_fixed');
					}
					if(this.varieties_arr[i].offsetTop < scrollTop) {
						this.current_varieties = i
						temp = i;
					}
				}
			},
			jump(id) {
//				this.$router.push({
//					path: '/details',
//					query: {
//						good_id: id
//					}
//				})
				openWebviewUrl("/packapp/foodshop/#/details?good_id="+id);
			}
		},
		mounted() {
			var _this = this;
			setTimeout(function() {
//					_this.varieties = _this.foodList.product_list;
//					console.log(_this.varieties)
				if(document.getElementsByClassName("food_varieties")[0]){
					document.getElementsByClassName("food_varieties")[0].setAttribute('class', 'food_varieties');
					document.getElementsByClassName("food_varieties_group")[0].setAttribute('class', 'food_varieties_group');
				}
			}, 200);
			window.addEventListener('scroll', this.onScrollMenu);
		},
		destroyed() {
			window.removeEventListener('scroll', this.onScrollMenu);
		},
		computed: {
			...mapState(["cart", "foodList", "cart","totalPrice","submit_menu"]),
			...mapGetters(["foodListChange"]),
			numberFixed() {
				return function(num) {
					return Number(num).toFixed(2);
				}
			},
			switchL() {
				return function(text) {
					return L_(text)
				}
			}
		}
	}
</script>

<style scoped="scoped">
	.el-container {
		padding: 0;
		width: 100%;
		margin-bottom: 100px;
		/*position: relative;*/
	}
	
	.el-container .el-aside {
		width: 180px !important;
	}
	
	.el-container .el-aside .varieties {
		width: 100%;
		height: 100px;
		background-color: rgb(242, 242, 242);
		line-height: 100px;
		font-size: 24px;
		font-family: 'HelveticaNeue-Medium';
		position: relative;
		z-index: 99;
		font-weight: 800;
	}
	
	.el-container .el-aside .active {
		background-color: rgb(33, 50, 67);
		color: rgb(255, 255, 255);
		border-radius: 0 20px 20px 0;
	}
	
	.el-container .el-aside .varieties .order_number {
		width: 40px;
		height: 40px;
		line-height: 40px;
		border-radius: 50%;
		background-color: rgb(92, 198, 204);
		color: rgb(255, 255, 255);
		position: absolute;
		top: 4px;
		right: 2px;
		transform: scale(0.7);
		-webkit-transform: scale(0.7);
	}
	
	.el-container .el-aside .varieties .varieties_pic {
		width: 33.2px;
		height: 33.2px;
		border-radius: 50%;
		display: inline-block;
		margin-right: 8.8px;
		line-height: 33.2px;
		/*float: left;*/
		/*margin-left: 40px;*/
		/*margin-top: 6px;*/
		vertical-align: middle;
	}
	
	.el-container .el-aside .varieties .varieties_pic img {
		width: 100%;
		height: 100%;
	}
	
	.el-container .el-main {
		padding: 0;
	}
	
	.el-container .el-main .food_varieties_group_fixed {
		padding-top: 60px;
	}
	
	.el-container .el-main .food_varieties {
		height: 60px;
		line-height: 60px;
		background-color: rgb(242, 242, 242);
		text-align: left;
		padding-left: 18px;
		font-size: 26px;
		font-family: 'HelveticaNeue-Medium';
		z-index: 99;
		font-weight: 800;
	}
	
	.el-container .el-main .food_varieties_fixed {
		position: fixed;
		top: 0;
		left: 180px;
		right: 0;
	}
	
	.el-container .el-main .food_varieties span {
		color: rgb(255, 56, 20);
		margin-left: 20px;
		font-weight:normal;
	}
	
	.el-container .el-main .food {
		height: 222px;
		text-align: left;
		border-bottom: 4px solid rgb(242, 242, 242);
	}
	
	.el-container .el-main .food img {
		width: 180px;
		height: 180px;
		margin: 20px 0;
	}
	
	.el-container .el-main .food .right {
		width: 356px;
		float: right;
		margin-right: 20.2px;
		height: 222px;
		position: relative;
	}
	
	.el-container .el-main .food .right_full {
		width: 540px !important;
		margin-left: 22px !important;
		margin-right: 22px !important;
	}
	
	.el-container .el-main .food .right .card_title {
		font-family: "HelveticaNeue-Medium";
		font-size: 32px;
		font-weight: bold;
		margin-top: 19.8px;
		height: 40px;
		display: inline-block;
	}
	
	.el-container .el-main .food .right .pepper {
		width: 30px;
		height: 30px;
		margin: 0;
		float: right;
		margin-top: 24px;
		margin-right: 20px;
	}
	
	.el-container .el-main .food .right .card_title_fixed {
		width: 85% !important;
	}
	
	.el-container .el-main .food .right .card_title,
	.el-container .el-main .food .right .card_introduction {
		color: rgb(0, 0, 0);
		display: inline-block;
		overflow: hidden;
		white-space: nowrap;
		text-overflow: ellipsis;
		width: 100%;
	}
	
	.el-container .el-main .food .right .card_introduction {
		font-size: 24px;
		margin-top: 2px;
	}
	
	.el-container .el-main .food .right .card_left {
		overflow: hidden;
		transform-origin: left;
		-webkit-transform-origin: left;
		transform: scale(0.7);
		-webkit-transform: scale(0.7);
		width: 100%;
		height: 90px;
		display: inline-block;
		margin-top: -6px;
	}
	
	.el-container .el-main .food .right .card_left .card_tags {
		height: 24px;
		border: 2px solid rgb(33, 50, 67);
		color: rgb(33, 50, 67);
		font-size: 16px;
		display: inline-block;
		line-height: 26px;
		border-radius: 4px;
		float: left;
		margin-right: 16px;
		padding: 4px 8px;
		margin-bottom: 10px;
	}
	
	.el-container .el-main .food .right .card_left .orange {
		color: rgb(255, 98, 0);
		border-color: rgb(255, 98, 0);
	}
	
	.el-container .el-main .food .right .card_left .card_tags .orangeIcon {
		width: 16px;
		height: 16px;
		border-radius: 50%;
		display: inline-block;
		text-align: center;
		margin: 0;
		margin-top: 2px;
		/*float: left;*/
		/*margin-right: 4px;*/
	}
	
	.el-container .el-main .food .right .now_price_container {
		position: absolute;
		left: 0;
		top: 164px;
		bottom: 21px;
	}
	
	.el-container .el-main .food .right .now_price {
		color: rgb(64, 64, 64);
		font-size: 32px;
		display: inline-block;
		font-weight: 600;
	}
	
	.el-container .el-main .food .right .past_price {
		color: rgb(64, 64, 64);
		font-size: 20px;
		display: inline-block;
		position: relative;
		/*left: 114px;*/
		vertical-align: top;
		/*top: 165px;*/
		margin-left: 14px;
	}
	
	.el-container .el-main .food .right .past_price::before {
		content: '';
		width: 100%;
		height: 2px;
		top: 12px;
		position: absolute;
		background-color: rgb(64, 64, 64);
	}
	
	.el-container .el-main .food .right .orange_price {
		color: rgb(255, 98, 0) !important;
	}
	
	.el-container .el-main .food .right .icon_add {
		width: 40px;
		height: 40px;
		position: absolute;
		right: 12px;
		bottom: 21px;
		margin: 0;
	}
	
	.el-container .el-main .food .right .icon_minus {
		width: 40px;
		height: 40px;
		position: absolute;
		right: 100px;
		bottom: 21px;
		margin: 0;
	}
	
	.el-container .el-main .food .right .food_order_number_add {
		font-size: 36px;
		position: absolute;
		bottom: 16px;
		right: 66px;
	}
	
	.el-container .el-main .food .right .max {
		font-size: 28px;
		color: rgb(92, 198, 204);
		position: absolute;
		right: 12px;
		bottom: 79px;
	}
	
	.el-container .el-main .food .right .choose {
		width: 120px;
		height: 50px;
		position: absolute;
		right: 0px;
		bottom: 21px;
		background-color: rgb(92, 198, 204);
		font-size: 24px;
		text-align: center;
		border-radius: 26px;
		padding: 0;
		color: rgb(255, 255, 255);
		line-height: 50px;
	}
	
	.el-container .el-main .food .right .max_fix {
		bottom: 22px;
	}
	
	.isFixed {
		position: fixed;
		left: 0;
		top: 0;
	}
</style>


